-- =====================================================================
-- V61: Rwanda administrative hierarchy
--   5 provinces, 30 districts, 416 sectors, 2,148 cells, 14,837 villages
--   Source: NISR administrative unit list. Village codes are the official
--   8-digit codes; names are normalized from the NISR extract.
--   UUID ids match BaseEntity (the dashboard edits these rows); the audit
--   columns let Hibernate create/update stamps validate against the schema.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Provinces
-- ---------------------------------------------------------------------
CREATE TABLE provinces (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    code       VARCHAR(2)  NOT NULL,
    name       VARCHAR(100) NOT NULL,
    is_enabled BOOLEAN     NOT NULL DEFAULT TRUE,
    allow_edit BOOLEAN     NOT NULL DEFAULT TRUE,
    version    BIGINT      NOT NULL DEFAULT 0,
    created_at TIMESTAMP   NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by VARCHAR(50),
    updated_at TIMESTAMP,
    updated_by VARCHAR(50),
    CONSTRAINT uk_provinces_code UNIQUE (code)
);
CREATE INDEX idx_provinces_name ON provinces (name);

-- ---------------------------------------------------------------------
-- Districts
-- ---------------------------------------------------------------------
CREATE TABLE districts (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    province_id UUID         NOT NULL,
    code        VARCHAR(2)   NOT NULL,
    name        VARCHAR(100) NOT NULL,
    is_enabled  BOOLEAN      NOT NULL DEFAULT TRUE,
    allow_edit  BOOLEAN      NOT NULL DEFAULT TRUE,
    version     BIGINT       NOT NULL DEFAULT 0,
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by  VARCHAR(50),
    updated_at  TIMESTAMP,
    updated_by  VARCHAR(50),
    CONSTRAINT uk_districts_code UNIQUE (code),
    CONSTRAINT fk_districts_province FOREIGN KEY (province_id)
        REFERENCES provinces (id) ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE INDEX idx_districts_province_id ON districts (province_id);
CREATE INDEX idx_districts_name ON districts (name);

-- ---------------------------------------------------------------------
-- Sectors
-- ---------------------------------------------------------------------
CREATE TABLE sectors (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    district_id UUID         NOT NULL,
    code        VARCHAR(4)   NOT NULL,
    name        VARCHAR(100) NOT NULL,
    is_enabled  BOOLEAN      NOT NULL DEFAULT TRUE,
    allow_edit  BOOLEAN      NOT NULL DEFAULT TRUE,
    version     BIGINT       NOT NULL DEFAULT 0,
    created_at  TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by  VARCHAR(50),
    updated_at  TIMESTAMP,
    updated_by  VARCHAR(50),
    CONSTRAINT uk_sectors_code UNIQUE (code),
    CONSTRAINT fk_sectors_district FOREIGN KEY (district_id)
        REFERENCES districts (id) ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE INDEX idx_sectors_district_id ON sectors (district_id);
CREATE INDEX idx_sectors_name ON sectors (name);

-- ---------------------------------------------------------------------
-- Cells
-- ---------------------------------------------------------------------
CREATE TABLE cells (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    sector_id  UUID         NOT NULL,
    code       VARCHAR(6)   NOT NULL,
    name       VARCHAR(100) NOT NULL,
    is_enabled BOOLEAN      NOT NULL DEFAULT TRUE,
    allow_edit BOOLEAN      NOT NULL DEFAULT TRUE,
    version    BIGINT       NOT NULL DEFAULT 0,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by VARCHAR(50),
    updated_at TIMESTAMP,
    updated_by VARCHAR(50),
    CONSTRAINT uk_cells_code UNIQUE (code),
    CONSTRAINT fk_cells_sector FOREIGN KEY (sector_id)
        REFERENCES sectors (id) ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE INDEX idx_cells_sector_id ON cells (sector_id);
CREATE INDEX idx_cells_name ON cells (name);

-- ---------------------------------------------------------------------
-- Villages
-- ---------------------------------------------------------------------
CREATE TABLE villages (
    id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    cell_id    UUID         NOT NULL,
    code       VARCHAR(8)   NOT NULL,
    name       VARCHAR(100) NOT NULL,
    is_enabled BOOLEAN      NOT NULL DEFAULT TRUE,
    allow_edit BOOLEAN      NOT NULL DEFAULT TRUE,
    version    BIGINT       NOT NULL DEFAULT 0,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by VARCHAR(50),
    updated_at TIMESTAMP,
    updated_by VARCHAR(50),
    CONSTRAINT uk_villages_code UNIQUE (code),
    CONSTRAINT fk_villages_cell FOREIGN KEY (cell_id)
        REFERENCES cells (id) ON DELETE RESTRICT ON UPDATE CASCADE
);
CREATE INDEX idx_villages_cell_id ON villages (cell_id);
CREATE INDEX idx_villages_name ON villages (name);


